scripts.草草对话.txt:
// 与草草对话

	If ($Saychake == 3) @Sub1;
	
	Say("“天草星”阿邦：我叫阿邦，你也是新来的兄弟吗？");
	Return;
	
@Sub1:
	If ($Talkcaocao == 0) @caocao0;
	If ($Talkcaocao == 1) @caocao1;
		
@caocao0:	
	Say("“天草星”阿邦：兄弟，有什么事要帮忙吗？");
	Say("独孤剑：你便是阿邦么？周旱大哥要我将这些东西给你看看，是不是你……", 1);
	Say("“天草星”阿邦：护腕……不错，这正是我落水时丢失的。");
	
	GetGoodsNum("Goods412_一只护腕.ini");
	If ($GoodsNum == 0) @Lable0;
	If ($GoodsNum == 1) @Lable1;
	
 @Lable0:
	Say("“天草星”阿邦：不知如何感谢这位兄弟……这些银子我就不要了，兄弟你就收下吧！");
	Say("独孤剑：这如何使得？", 1);
	Say("“天草星”阿邦：反正兄弟我在这也用不着银子，就当兄弟我的一番心意了。");
	Say("独孤剑（暗想）：这银子还是还给王老五吧。", 1);
	DelGoods("Goods413_另一只护腕.ini");
	Assign($Talkcaocao, 1);
	Return;
	
 @Lable1:
	Say("独孤剑：你可是中都人士，你有一个生死之交叫作“云笑风”，你原名叫作“草草”？", 1);
	Say("“天草星”阿邦：你，你怎么知道的？");
	Say("独孤剑：这护腕原本乃是一对……你可认得这一只！", 1);
	Say("“天草星”阿邦：啊，云大哥……");
	Say("独孤剑：云兄为了你，不远万里，南下江南……", 1);
	
	FadeOut();
	Say("独孤剑把事情的来龙去脉讲述给了草草。");
	Say(500);
	FadeIn();
	
	Say("“天草星”阿邦：那日，我们的商船被一伙强盗打劫，他们见值钱的就抢，抢完之后还大开杀戒，连妇孺婴孩都不放过……");
	Say("独孤剑：他们为什么要杀人，太残忍了！", 5);
	Say("“天草星”阿邦：因为他们就是官兵！所以，他们要杀人灭口……");
	Say("独孤剑：什么？！", 6);
	Say("“天草星”阿邦：他们是被金兵击溃的宋兵，一路上烧杀掳掠，比金人还残忍……我不甘被杀，跳进了湖中，本以为自己只有死路一条，没想到……");
	Say("“天草星”阿邦：醒来之后，我便在这里了。经此一劫，自己经营的资本都化为乌有，心灰意懒，本想一死了之。但这里的弟兄们待我如同亲生兄弟，个个义薄云天，肝胆相照，行血性之举，为忠义之道……想想以前的所作所求，反而不值一哂。哈哈哈哈……");
	Say("独孤剑：原来如此。那云兄为你历尽艰辛……", 1);
	Say("“天草星”阿邦：我也无日不思念兄长。可是，兄弟已经落草于此，回去恐怕会连累兄长！");
	Say("独孤剑：云兄为你已散尽家资，无论如何，你应当告知于他，也好让他放心。", 1);
	Say("“天草星”阿邦：散尽家资？兄长他——都是我的罪过……好，我现在就去求周大哥让我回中都一趟。倘若兄长仍不嫌弃于我，当邀兄长同来此地，共干一番轰轰烈烈的大事；倘若兄长怪罪，我唯有一死以谢兄长知己之恩。");
	Say("独孤剑：兄台果然也是性情中人！在下祝你和云兄早日团聚。", 2);
	Say("“天草星”阿邦：多谢！");
	
	NpcGoto("草草", 23, 34);
	NpcGoto("草草", 20, 39);
	DelNpc("草草");
	SaveNpc();
	DelGoods("Goods412_一只护腕.ini");
	DelGoods("Goods413_另一只护腕.ini");
	AddMoney(-1000);
	Assign($Talkcaocao, 2);
	Return;
	
@caocao1:	
 	Say("“天草星”阿邦：多谢这位兄弟！");
	Return;

